    fontWeight: FontWeight.w400,
  );

  /// `overline` (Text): Тип записи на этикетке и шапки разделов паспорта.
  /// Только прописными. Sample: VACCINATION · ВАКЦИНАЦИЯ
  static const overline = CbTypeSpec(
    name: 'overline',
    family: CbFontFamily.sans,
    fontSize: 11,
    height: 14 / 11,
    fontWeight: FontWeight.w500,
    letterSpacing: 0.44, // 0.04em
  );

  /// `code` (Code): Номер чипа (группы по 3), серия вакцины, номер паспорта.
  /// Sample: 276 098 100 123 456
  static const code = CbTypeSpec(
    name: 'code',
    family: CbFontFamily.mono,
    fontSize: 14,
    height: 20 / 14,
    fontWeight: FontWeight.w500,
    letterSpacing: 0.28, // 0.02em
  );

  /// Every style, in token order.
  static const all = <CbTypeSpec>[
    displayXl,
    displayLg,
    numeral,
    title,
    subtitle,
    body,
    bodySm,
    label,
    caption,
    overline,
    code,
  ];
}
